import{_ as e,o as a,c as i,aj as r}from"./chunks/framework.BwH0p-pt.js";const c=JSON.parse('{"title":"Attributes","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/attribute/index.md","filePath":"2.1/attribute/index.md","lastUpdated":1785836850000}'),s={name:"2.1/attribute/index.md"};function o(n,t,l,d,h,u){return a(),i("div",null,[...t[0]||(t[0]=[r(`<h1 id="attributes" tabindex="-1">Attributes <a class="header-anchor" href="#attributes" aria-label="Permalink to &quot;Attributes&quot;">​</a></h1><p>An <strong>attribute</strong> is a single characteristic of a product — <em>Color</em>, <em>Size</em>, <em>Brand</em>, <em>Price</em>, <em>SKU</em>, <em>Description</em>, <em>Stock</em>. The full set of attributes assigned to a product is what gives that product its shape: which fields appear on its edit page, which values the storefront can display, which rules validate the data.</p><p>UnoPim&#39;s attribute system has three building blocks that fit together:</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[Attribute] --&gt;|Bundled into| G[Attribute Group]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G --&gt;|Assigned to| F[Attribute Family]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt;|Decides layout for| P[Product Edit Page]</span></span></code></pre></div><p>Assigning a product to a family picks its editable fields; groups control how those fields are laid out on the page; attributes carry the actual values.</p><p>Assigning a product to a family picks its editable fields; groups control how those fields are laid out on the page; attributes carry the actual values.</p><h2 id="what-s-in-this-section" tabindex="-1">What&#39;s in this section <a class="header-anchor" href="#what-s-in-this-section" aria-label="Permalink to &quot;What&#39;s in this section&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it covers</th></tr></thead><tbody><tr><td><strong><a href="./attribute-input.html">Attribute Input Type</a></strong></td><td>The 12 data types an attribute can carry (Text, Textarea, Boolean, Select, Multiselect, Datetime, Date, Image, Gallery, File, Checkbox, Price) plus the <strong>Swatch Types</strong> (Color / Image / Text) introduced in v2.0.</td></tr><tr><td><strong><a href="./product-attribute.html">Product Attribute</a></strong></td><td>How to create an attribute end-to-end — general fields, label translations, validations, configuration (Value Per Locale / Value Per Channel / Is Filterable), plus the 12 data-type inputs shown in action.</td></tr><tr><td><strong><a href="./attribute-family.html">Attribute Family</a></strong></td><td>How to create a family and drag attributes into its groups so products in that family show the right fields.</td></tr><tr><td><strong><a href="./attribute-groups.html">Attribute Groups</a></strong></td><td>How to bundle attributes into a group so they render together in a dedicated card on the product edit page.</td></tr></tbody></table><h2 id="key-concepts-at-a-glance" tabindex="-1">Key concepts at a glance <a class="header-anchor" href="#key-concepts-at-a-glance" aria-label="Permalink to &quot;Key concepts at a glance&quot;">​</a></h2><ul><li><strong>Every attribute has a data type</strong> — see <a href="./attribute-input.html">Attribute Input Type</a>. The data type determines the input control and the allowed values.</li><li><strong>Every attribute belongs to a group</strong> — groups are purely organisational, but they drive the layout of the product edit page. See <a href="./attribute-groups.html">Attribute Groups</a>.</li><li><strong>Every product belongs to a family</strong> — the family decides which groups (and therefore which attributes) appear on that product. See <a href="./attribute-family.html">Attribute Family</a>.</li><li><strong>Attributes can vary by locale, by channel, or both.</strong> Configure this under the Configuration card when creating an attribute. This is how you store a separate Description per language, or a separate Price per storefront.</li><li><strong>Attributes marked <code>Is Filterable</code></strong> show up in the <strong>Apply Filters</strong> drawer on the Products listing, so your team can filter products by that attribute&#39;s values.</li></ul><h2 id="v2-0-highlights" tabindex="-1">v2.0 highlights <a class="header-anchor" href="#v2-0-highlights" aria-label="Permalink to &quot;v2.0 highlights&quot;">​</a></h2><ul><li><strong>Swatch Types</strong> — Select and Multiselect attributes can render as visual swatches (Color, Image, or Text) instead of plain dropdowns.</li><li><strong>Video Support</strong> in the Gallery attribute — upload and manage video files alongside images.</li><li><strong>Per-attribute filtering</strong> — toggle <strong>Is Filterable</strong> on an attribute and it appears in the Products listing&#39;s <strong>Add Filter</strong> drawer immediately, no reindex needed.</li></ul><p>Jump to a sub-page above to see the step-by-step guide for each.</p>`,13)])])}const g=e(s,[["render",o]]);export{c as __pageData,g as default};
